do $migration$
declare
  v_steps jsonb := $steps$[{"id":"intro","kind":"intro","title":"Qual é sua maturidade para construir um PMO que gera valor?","body":"Você já participa hoje da construção, operação ou transformação de um PMO?\n[[QF_INTRO_IMAGE:https://forms.trentim.com/books/estrategia-em-acao-pmo-vmo.webp]]","cta":"Começar diagnóstico","art":"hero"},{"id":"pmo-experience-response","kind":"branch","variants":{"sim":{"title":"Você já está dentro do jogo. Agora vamos medir o seu próximo salto.","body":"Experiência em PMO ajuda, mas o diferencial profissional aparece quando você consegue diagnosticar o contexto, influenciar decisões e transformar o escritório em uma estrutura percebida por gerar valor."},"nao":{"title":"Este é um ótimo momento para construir uma base sólida.","body":"Você não precisa já liderar um PMO para desenvolver as competências certas. O diagnóstico vai mostrar o quanto você está preparado para estruturar, reposicionar ou evoluir um escritório de projetos."}}},{"id":"pmo-q1","kind":"question","title":"Consigo identificar quando uma organização realmente precisa de um PMO e qual problema ele deve resolver.","input":"scale","dimension":"visao_estrategica","options":[{"label":"Discordo totalmente","value":"1","score":0},{"label":"Discordo","value":"2","score":1},{"label":"Nem concordo nem discordo","value":"3","score":2},{"label":"Concordo","value":"4","score":3},{"label":"Concordo totalmente","value":"5","score":4}]},{"id":"pmo-q2","kind":"question","title":"Consigo definir qual tipo de PMO faz mais sentido para diferentes contextos, em vez de aplicar um modelo pronto.","input":"scale","dimension":"arquitetura_pmo","options":[{"label":"Discordo totalmente","value":"1","score":0},{"label":"Discordo","value":"2","score":1},{"label":"Nem concordo nem discordo","value":"3","score":2},{"label":"Concordo","value":"4","score":3},{"label":"Concordo totalmente","value":"5","score":4}]},{"id":"pmo-q3","kind":"question","title":"Se recebesse hoje a responsabilidade de estruturar ou reorganizar um PMO, saberia por onde começar.","input":"scale","dimension":"arquitetura_pmo","options":[{"label":"Discordo totalmente","value":"1","score":0},{"label":"Discordo","value":"2","score":1},{"label":"Nem concordo nem discordo","value":"3","score":2},{"label":"Concordo","value":"4","score":3},{"label":"Concordo totalmente","value":"5","score":4}]},{"id":"pmo-q4","kind":"question","title":"Consigo conectar projetos, programas e portfólio aos objetivos estratégicos da organização.","input":"scale","dimension":"visao_estrategica","options":[{"label":"Discordo totalmente","value":"1","score":0},{"label":"Discordo","value":"2","score":1},{"label":"Nem concordo nem discordo","value":"3","score":2},{"label":"Concordo","value":"4","score":3},{"label":"Concordo totalmente","value":"5","score":4}]},{"id":"pmo-q5","kind":"question","title":"Sei definir indicadores que demonstrem o valor do PMO para a liderança, e não apenas o andamento dos projetos.","input":"scale","dimension":"gestao_valor","options":[{"label":"Discordo totalmente","value":"1","score":0},{"label":"Discordo","value":"2","score":1},{"label":"Nem concordo nem discordo","value":"3","score":2},{"label":"Concordo","value":"4","score":3},{"label":"Concordo totalmente","value":"5","score":4}]},{"id":"pmo-q6","kind":"question","title":"Tenho segurança para conversar com a alta liderança sobre prioridades, governança, investimentos e geração de valor.","input":"scale","dimension":"governanca_influencia","options":[{"label":"Discordo totalmente","value":"1","score":0},{"label":"Discordo","value":"2","score":1},{"label":"Nem concordo nem discordo","value":"3","score":2},{"label":"Concordo","value":"4","score":3},{"label":"Concordo totalmente","value":"5","score":4}]},{"id":"pmo-context-1","kind":"insight","eyebrow":"PMI | competências e maturidade","title":"Construir um PMO exige muito mais do que conhecer processos.","body":"O desafio não é dominar tudo de uma vez. É identificar quais competências você já possui e quais precisa desenvolver para atuar no contexto certo.","icons":[{"emoji":"30","text":"competências essenciais para profissionais de PMO"},{"emoji":"26","text":"serviços comuns de PMO"},{"emoji":"5","text":"níveis de maturidade para avaliar os serviços"},{"emoji":"8","text":"cenários organizacionais que podem exigir abordagens diferentes"}],"stat":"Seu diagnóstico está analisando exatamente isso: o seu preparo para construir, adaptar e evoluir um PMO.","source":"PMI, Escritórios de Gerenciamento de Projetos: Um Guia Prático, 2025","visual":"chart"},{"id":"pmo-q7","kind":"question","title":"Você foi chamado para criar um PMO em uma empresa onde os projetos atrasam, as áreas trabalham de formas diferentes e a liderança reclama da falta de visibilidade. Qual seria sua primeira ação?","input":"single","dimension":"arquitetura_pmo","options":[{"label":"Criaria imediatamente templates e uma metodologia única.","value":"0","score":0},{"label":"Implantaria uma ferramenta para centralizar os projetos.","value":"1","score":1},{"label":"Mapearia projetos, processos e principais problemas antes de definir a estrutura.","value":"2","score":2},{"label":"Faria um diagnóstico do contexto, estratégia, maturidade, problemas e expectativas da liderança antes de desenhar o PMO.","value":"3","score":3}]},{"id":"pmo-q8","kind":"question","title":"Ao desenhar esse PMO, como você decidiria entre um modelo de Suporte, Controle ou Diretivo?","input":"single","dimension":"arquitetura_pmo","options":[{"label":"Escolheria o modelo que considero mais completo.","value":"0","score":0},{"label":"Utilizaria o modelo mais comum no mercado.","value":"1","score":1},{"label":"Consideraria principalmente o tamanho da empresa.","value":"2","score":2},{"label":"Avaliaria maturidade, cultura, riscos, autonomia, complexidade e necessidades estratégicas.","value":"3","score":3}]},{"id":"pmo-q9","kind":"question","title":"A liderança pergunta: “Para que exatamente precisamos desse PMO?”. Qual seria sua resposta?","input":"single","dimension":"visao_estrategica","options":[{"label":"Para acompanhar cronogramas e controlar os projetos.","value":"0","score":0},{"label":"Para padronizar processos e melhorar a organização.","value":"1","score":1},{"label":"Para aumentar visibilidade, governança e apoio às decisões.","value":"2","score":2},{"label":"Para conectar estratégia, execução e geração de valor por meio dos projetos.","value":"3","score":3}]},{"id":"pmo-context-2","kind":"insight","eyebrow":"PMI | contexto antes do modelo","title":"Não existe um modelo de PMO que funcione para todas as organizações.","body":"Segundo o PMI, o papel, a estrutura e os serviços de um PMO precisam se adaptar ao contexto, à cultura, à maturidade e às necessidades reais da organização.","stat":"Maturidade não é saber copiar um modelo. É saber diagnosticar o contexto e construir o PMO certo para ele.","source":"PMI, Escritórios de Gerenciamento de Projetos: Um Guia Prático, 2025","visual":"sparkle"},{"id":"pmo-q10","kind":"question","title":"O PMO está funcionando, mas a liderança o enxerga apenas como a área que cobra cronogramas. O que você faria?","input":"single","dimension":"governanca_influencia","options":[{"label":"Passaria a cobrar atualizações com mais frequência.","value":"0","score":0},{"label":"Melhoraria os relatórios e os dashboards.","value":"1","score":1},{"label":"Reforçaria governança, indicadores executivos e rituais de decisão.","value":"2","score":2},{"label":"Reposicionaria o PMO para conectar estratégia, priorização, decisões e valor percebido.","value":"3","score":3}]},{"id":"pmo-q11","kind":"question","title":"Há dez projetos disputando recursos e todos os gestores dizem que seus projetos são prioritários. Como você conduziria essa situação?","input":"single","dimension":"visao_estrategica","options":[{"label":"Atenderia primeiro os projetos dos gestores mais influentes.","value":"0","score":0},{"label":"Tentaria negociar caso a caso.","value":"1","score":1},{"label":"Aplicaria critérios de priorização previamente definidos.","value":"2","score":2},{"label":"Usaria critérios de valor, alinhamento estratégico, capacidade, risco e impacto no portfólio.","value":"3","score":3}]},{"id":"pmo-q12","kind":"question","title":"Um executivo quer iniciar imediatamente um projeto importante, mas você percebe que não existe capacidade disponível e que outras iniciativas podem gerar mais valor. O que você faria?","input":"single","dimension":"governanca_influencia","options":[{"label":"Iniciaria o projeto, por ser uma solicitação executiva.","value":"0","score":0},{"label":"Sugeriria começar mesmo assim e ajustar depois.","value":"1","score":1},{"label":"Levaria o tema para uma decisão estruturada com dados.","value":"2","score":2},{"label":"Apresentaria impacto em capacidade, portfólio, riscos e valor para orientar uma decisão estratégica.","value":"3","score":3}]},{"id":"pmo-context-3","kind":"insight","eyebrow":"PMI | influência estratégica","title":"O PMO ganha relevância quando consegue influenciar decisões.","body":"O PMO moderno precisa ir além do acompanhamento operacional. Ele conecta projetos à estratégia, apoia decisões e traduz sua contribuição em uma linguagem que faça sentido para a liderança.","stat":"Conhecer processos é importante. Conseguir transformar informação em decisão estratégica é outro nível de atuação.","source":"PMI, Escritórios de Gerenciamento de Projetos: Um Guia Prático, 2025","visual":"people"},{"id":"pmo-q13","kind":"question","title":"Como você demonstraria que um PMO está gerando valor?","input":"single","dimension":"gestao_valor","options":[{"label":"Pela quantidade de projetos acompanhados.","value":"0","score":0},{"label":"Pelo cumprimento de prazo, custo e escopo.","value":"1","score":1},{"label":"Pela melhoria na previsibilidade e no apoio às decisões.","value":"2","score":2},{"label":"Pela conexão entre investimentos, benefícios, estratégia e valor gerado.","value":"3","score":3}]},{"id":"pmo-q14","kind":"question","title":"Um projeto foi concluído dentro do prazo, custo e escopo, mas os benefícios esperados não apareceram. Como você avaliaria o resultado?","input":"single","dimension":"gestao_valor","options":[{"label":"Como sucesso, porque o projeto foi entregue corretamente.","value":"0","score":0},{"label":"Como sucesso parcial, porque a execução foi boa.","value":"1","score":1},{"label":"Como um sinal de que faltou acompanhamento dos resultados.","value":"2","score":2},{"label":"Como evidência de que entrega não basta: é preciso medir benefícios e valor gerado.","value":"3","score":3}]},{"id":"pmo-q15","kind":"question","title":"Se você tivesse que transformar um PMO tradicional em uma estrutura mais orientada a valor, qual seria sua prioridade?","input":"single","dimension":"gestao_valor","options":[{"label":"Criar mais controles.","value":"0","score":0},{"label":"Padronizar ainda mais os projetos.","value":"1","score":1},{"label":"Melhorar governança e indicadores estratégicos.","value":"2","score":2},{"label":"Conectar decisões de portfólio, investimentos, benefícios e resultados de negócio.","value":"3","score":3}]},{"id":"pmo-context-4","kind":"insight","eyebrow":"PMI | PMO orientado por valor","title":"O próximo nível do PMO não é mais controle. É valor.","body":"O PMI propõe uma mudança de mentalidade: sair de um PMO centrado em processos e caminhar para uma estrutura orientada às necessidades dos clientes, aos resultados e à geração contínua de valor.","icons":[{"emoji":"1","text":"Entender necessidades e criar conscientização"},{"emoji":"2","text":"Construir uma proposta de valor e desenvolver serviços"},{"emoji":"3","text":"Integrar, operar e monitorar os serviços"},{"emoji":"4","text":"Melhorar, entregar valor e fazer esse valor ser reconhecido"}],"stat":"Sua maturidade profissional aparece na capacidade de conduzir esse ciclo — não apenas de controlar projetos.","source":"PMI, Escritórios de Gerenciamento de Projetos: Um Guia Prático, 2025 — PMO Value Ring™","visual":"chart"},{"id":"pmo-pattern","kind":"insight","eyebrow":"Quase lá","title":"Seu diagnóstico já consegue enxergar um padrão claro.","body":"Estamos cruzando sua visão estratégica, confiança, aplicação prática, capacidade de decisão e nível de estruturação para chegar ao seu perfil.","stat":"Seu resultado é construído a partir das suas respostas, não de um teste genérico.","visual":"sparkle"},{"id":"salary-range","kind":"question","title":"Qual é sua faixa salarial atual?","subtitle":"Isso nos ajuda a contextualizar seu momento profissional.","input":"single","options":[{"label":"Até R$ 5.000","value":"faixa1","emoji":"💵"},{"label":"R$ 5.001 a R$ 10.000","value":"faixa2","emoji":"💼"},{"label":"R$ 10.001 a R$ 15.000","value":"faixa3","emoji":"📈"},{"label":"R$ 15.001 a R$ 25.000","value":"faixa4","emoji":"🚀"},{"label":"Acima de R$ 25.000","value":"faixa5","emoji":"🏆"}]},{"id":"email","kind":"email","title":"Seu diagnóstico está quase pronto. Qual e-mail devemos usar para liberar o resultado?"},{"id":"name","kind":"name","title":"E como podemos chamar você?"},{"id":"processing","kind":"processing","title":"Gerando seu diagnóstico de maturidade em PMO/VMO..."},{"id":"insight-pre-result-guide","kind":"insight","eyebrow":"Seu mapa profissional está pronto","title":"Mas antes, vamos para seu resultado {{nome}}!","body":"Organizamos suas respostas para mostrar seu nível atual, os pontos fortes que você já pode colocar em prática e as competências que mais podem acelerar sua evolução em PMO e VMO.","stat":"Da execução de projetos à capacidade de influenciar estratégia e valor.","source":"PMI, Escritórios de Gerenciamento de Projetos: Um Guia Prático, 2025","visual":"sparkle"},{"id":"result","kind":"result"}]$steps$::jsonb;
